/**
 * An onboarding checklist: the tasks with a done mark, a progress bar or a count. Axes: layout (card, plain),
 * progress (bar, text, none), marker (check, number), tone (default, muted).
 */
import { type ReactNode } from "react";
import { Disclosure, IconBadge, List, ListItem, Progress, Stack, Summary, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { Task } from "./checklist.types";

export type ChecklistProps = {
  id: string;
  title: string;
  tasks: Task[];
  empty?: string;
  progressLabel: string;
  layout?: "card" | "plain";
  progress?: "bar" | "text" | "none";
  marker?: "check" | "number";
  detail?: "always" | "expand";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function Checklist({
  id,
  title,
  tasks,
  empty = "",
  progressLabel,
  layout = "card",
  progress = "bar",
  marker = "check",
  detail = "always",
  tone = "default",
  landmarkLabel,
}: ChecklistProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} measure="2xl" landmarkLabel={landmarkLabel}>
      {((tasks?.length ?? 0) === 0) ? (
        <EmptyState icon="list-checks" title={empty} />
      ) : (
        <Stack
          gap="4"
          align="stretch"
          className={
            (layout as string) === "card" ? "rounded bg-card p-6 inset-ring inset-ring-border"
            : ""
          }
          data-testid="checklist"
        >
          {((progress as string) === "bar") ? (
            <Progress
              value={
                Math.round(((tasks.filter((i) => i["done"]).length * 100) / (tasks?.length ?? 0))) == null ? undefined
                : String(Math.round(((tasks.filter((i) => i["done"]).length * 100) / (tasks?.length ?? 0))))
              }
              max="100"
              aria-label={tpl(progressLabel, tasks.filter((i) => i["done"]).length, (tasks?.length ?? 0))}
            />
          ) : null}
          {((progress as string) === "text") ? (
            <Text size="sm" className="text-muted-foreground" data-testid="progress-text">
              {tpl(progressLabel, tasks.filter((i) => i["done"]).length, (tasks?.length ?? 0))}
            </Text>
          ) : null}
          <List className="m-0 flex list-none flex-col gap-4 p-0" data-testid="items">
            {(tasks ?? []).map((task, i) => (
              <ListItem key={task.id}
                className="flex items-start gap-4"
                data-testid="item"
                data-done={(task.done == null ? undefined : String(task.done))}
              >
                {((marker as string) === "number") ? (
                  <IconBadge variant={(task.done ? "primary" : "outline")} size="xs">
                    {((i + 1) == null ? undefined : String((i + 1)))}
                  </IconBadge>
                ) : (
                  <LucideIcon
                    name={(task.done ? "circle-check" : "circle")}
                    size={24}
                    className={(task.done ? "shrink-0 text-primary" : "shrink-0 text-muted-foreground")}
                  />
                )}
                {((detail as string) === "expand") ? (
                  <Disclosure variant="ghost" className="flex-1" data-testid="task-detail">
                    <Summary variant="ghost">
                      {task.title}
                    </Summary>
                    <Text size="sm" className="pb-2 text-muted-foreground">
                      {task.text}
                    </Text>
                  </Disclosure>
                ) : (
                  <Stack gap="0">
                    <Text size="base" weight="semibold">
                      {task.title}
                    </Text>
                    <Text size="sm" className="text-muted-foreground">
                      {task.text}
                    </Text>
                  </Stack>
                )}
              </ListItem>
            ))}
          </List>
        </Stack>
      )}
    </SectionFrame>
  );
}

